var GUIDES_JSON="{\n  \"revision\": \"coaching-draft-0.1\",\n  \"status\": \"editorial-draft-unreviewed\",\n  \"note\": \"General situational tutorials only; not meta predictions, personal decisions, or placement analysis.\",\n  \"guides\": {\n    \"26000004\": {\n      \"focus\": \"نیروی سنگین با آسیب تک‌هدفه برای پاسخ به تهدیدهای زمینی مقاوم.\",\n      \"attack\": \"پس از دفاع موفق و با پشتیبانی مناسب می‌تواند به ضدحمله تبدیل شود؛ مراقب هزینه بالای سرمایه‌گذاری باش.\",\n      \"defense\": \"در برابر بسیاری از واحدهای زمینی پرجان می‌تواند نقش آسیب اصلی را داشته باشد؛ با پوشش هوایی و پاسخ به Swarm تکمیل شود.\",\n      \"threats\": \"گروه‌های متعدد نیروهای ارزان و واحدهای هوایی می‌توانند زمان و اکسیر زیادی از آن بگیرند.\",\n      \"mistake\": \"قرار دادن بدون پشتیبانی و بدون آمادگی برای فشار در لاین دیگر.\",\n      \"quality\": \"راهنمای عمومی؛ Matchup و Balance جاری بازبینی نشده‌اند.\"\n    },\n    \"26000010\": {\n      \"focus\": \"کارت ۱ اکسیر برای چرخه و کمک دفاعی در موقعیت‌های مناسب.\",\n      \"attack\": \"به بازگشت کارت کلیدی کمک می‌کند، ولی سرعت واقعی چرخه از جمع هزینه‌ها به دست نمی‌آید.\",\n      \"defense\": \"برای منحرف‌کردن یا تأخیر بعضی تهدیدها کاربرد دارد، اما نباید در برابر آسیب ناحیه‌ای بی‌محابا استفاده شود.\",\n      \"threats\": \"واحدهای آسیب ناحیه‌ای و طلسم‌ها.\",\n      \"mistake\": \"مصرف بی‌هدف کارت ارزان فقط برای حرکت چرخه، بدون بررسی اکسیر باقی‌مانده.\",\n      \"quality\": \"نقش عمومی؛ تکامل فعال از سطح کارت به‌تنهایی قابل استنتاج نیست.\"\n    },\n    \"26000011\": {\n      \"focus\": \"مدافع زمینی با آسیب ناحیه‌ای و پایداری مناسب در برابر گروه‌ها.\",\n      \"attack\": \"پس از دفاع می‌تواند جلوتر از پشتیبان‌های آسیب‌رسان حرکت کند.\",\n      \"defense\": \"برای کنترل گروه‌های زمینی مفید است؛ در برابر تهدید هوایی به کارت دیگری نیاز دارد.\",\n      \"threats\": \"واحدهای هوایی و دورزن در صورت نبود پشتیبانی.\",\n      \"mistake\": \"تلقی‌کردن کارت ناحیه‌ای زمینی به‌عنوان پوشش کامل دفاع هوایی.\",\n      \"quality\": \"ارزش واقعی به ترکیب حریف و محل اجرا بستگی دارد.\"\n    },\n    \"26000014\": {\n      \"focus\": \"دفاع تک‌هدفه برددار با توان درگیری با واحدهای هوایی و زمینی.\",\n      \"attack\": \"پشت واحدهای مقاوم یا پس از دفاع موفق، با مراقبت از طلسم‌های حریف ارزش بیشتری پیدا می‌کند.\",\n      \"defense\": \"در مقابل تهدیدهای هوایی می‌تواند نقش اصلی داشته باشد؛ تنها گذاشتن آن در برابر گروه‌ها ریسک دارد.\",\n      \"threats\": \"طلسم‌های مناسب و فشار هم‌زمان دو لاین می‌توانند نگه‌داری آن را سخت کنند.\",\n      \"mistake\": \"خرج کردن تنها ضد‌هوایی دک در موقعیتی که تهدید هوایی حریف هنوز باقی است.\",\n      \"quality\": \"نقش عمومی، نه توصیه قطعی Matchup.\"\n    },\n    \"26000021\": {\n      \"focus\": \"Win Condition متکی بر فشار مستقیم به برج؛ چرخه و زمان‌بندی مهم‌اند.\",\n      \"attack\": \"به چرخه ساختمان دفاعی حریف و اکسیر باقی‌مانده خودت توجه کن؛ فشارهای پشت‌سرهم همیشه بهتر از حمله بزرگ نیستند.\",\n      \"defense\": \"خود Hog Rider دفاع هوایی یا پاسخ جامع به تانک‌ها نیست؛ سایر کارت‌های دک باید این نقش را پوشش دهند.\",\n      \"threats\": \"ساختمان‌های دفاعی و پاسخ‌های کم‌هزینه می‌توانند ارزش یک حمله تنها را کم کنند.\",\n      \"mistake\": \"فرستادن Hog بدون بررسی مسیر کارت‌ها و سپس نداشتن اکسیر برای دفاع.\",\n      \"quality\": \"توضیح عمومی و شرطی؛ وضعیت واقعی چرخه حریف از Battle Log مشخص نمی‌شود.\"\n    },\n    \"26000032\": {\n      \"focus\": \"نیروی دارای قابلیت ورود به نقطه انتخابی برای ایجاد فشار و آسیب تدریجی.\",\n      \"attack\": \"در ترکیب با فشارهای مکمل می‌تواند حریف را وادار به پاسخ کند.\",\n      \"defense\": \"می‌تواند نقش گذرایی در دفاع داشته باشد، اما Win Condition بودنش دلیل کافی برای جانشینی مدافع اصلی نیست.\",\n      \"threats\": \"پیش‌بینی‌پذیری جای ورود و مدافعان کم‌هزینه حریف.\",\n      \"mistake\": \"تکرار یک الگوی حمله بدون توجه به پاسخ‌های حریف.\",\n      \"quality\": \"بدون Replay نمی‌توان محل دقیق قرارگیری را تحلیل کرد.\"\n    },\n    \"26000049\": {\n      \"focus\": \"گروه هوایی بسیار ارزان برای آسیب پشتیبان و دفاع شرطی.\",\n      \"attack\": \"در صورت مصرف پاسخ ناحیه‌ای حریف می‌تواند فشار تکمیلی ایجاد کند.\",\n      \"defense\": \"برای مشغول‌کردن برخی واحدها مفید است؛ مقاومت کمی در برابر آسیب ناحیه‌ای دارد.\",\n      \"threats\": \"طلسم‌های سبک و واحدهای دارای آسیب ناحیه‌ای.\",\n      \"mistake\": \"استفاده هم‌زمان با کارت‌های آسیب‌پذیر دیگر و دادن ارزش به یک طلسم.\",\n      \"quality\": \"راهنمای عمومی؛ وضعیت کارت‌های حریف از داده صرفاً خلاصه قابل اثبات نیست.\"\n    },\n    \"26000055\": {\n      \"focus\": \"نیروی پرهزینه با آسیب ناحیه‌ای هنگام ورود و فشار زمینی.\",\n      \"attack\": \"پس از گرفتن ارزش دفاعی می‌تواند پایه ضدحمله شود؛ حمایت آن را با وضعیت اکسیر بسنج.\",\n      \"defense\": \"برای گروه‌های زمینی ارزش بالقوه دارد، اما جایگزین تمام پاسخ‌های تک‌هدفه یا دفاع هوایی نیست.\",\n      \"threats\": \"نیروهای دورزن، تانک‌کننده‌های کم‌هزینه و پوشش هوایی می‌توانند پیشروی را کند کنند.\",\n      \"mistake\": \"استفاده واکنشی از کارت ۷ اکسیر برای تهدیدی که پاسخ ارزان‌تری دارد.\",\n      \"quality\": \"توضیح عمومی؛ نتیجه مقابله به لول، چرخه و موقعیت بستگی دارد.\"\n    },\n    \"26000056\": {\n      \"focus\": \"ابزار فشار با واحد هوایی حامل و سربازهای پس از نابودی؛ Win Condition احتمالی.\",\n      \"attack\": \"می‌تواند برای وادارکردن حریف به پاسخ و ساخت فشار مکمل استفاده شود.\",\n      \"defense\": \"نقش دفاعی اصلی ندارد؛ دک باید برای پاسخ به تهدیدهای هوا و زمین آماده باشد.\",\n      \"threats\": \"ضد‌هوایی مناسب و طلسم‌هایی که با زمان درست ارزش بالایی می‌گیرند.\",\n      \"mistake\": \"فرض اینکه هر Skeleton Barrel بدون پوشش یا پشتیبانی به برج می‌رسد.\",\n      \"quality\": \"تحلیل مسیر حمله نیاز به Replay دارد.\"\n    },\n    \"27000000\": {\n      \"focus\": \"ساختمان دفاعی کم‌هزینه برای منحرف‌کردن یا مهار برخی تهدیدهای زمینی.\",\n      \"attack\": \"ابزار اصلی حمله نیست؛ ارزش آن به حفظ دفاع و چرخه کارت‌هاست.\",\n      \"defense\": \"محل و زمان قرارگیری اهمیت دارند؛ Battle Log به‌تنهایی نشان نمی‌دهد Cannon کجا گذاشته شده است.\",\n      \"threats\": \"نیروهای هوایی را به‌تنهایی هدف نمی‌گیرد و در برابر فشار چندجهته نیازمند پشتیبانی است.\",\n      \"mistake\": \"فرض اینکه وجود ساختمان، همه ضعف‌های دفاعی دک را رفع می‌کند.\",\n      \"quality\": \"راهنمای دفاعی عمومی؛ مختصات دقیق در MVP تجویز نمی‌شود.\"\n    },\n    \"28000000\": {\n      \"focus\": \"طلسم آسیب ناحیه‌ای با هزینه متوسط برای گرفتن ارزش از چند هدف.\",\n      \"attack\": \"اگر هم‌زمان به واحدها و برج ارزش می‌دهد، بررسی کن که آیا ۴ اکسیر توجیه دارد.\",\n      \"defense\": \"برای گروه‌های با جان مناسب می‌تواند مکمل دفاع باشد؛ نباید تنها پاسخ هر نوع Swarm تصور شود.\",\n      \"threats\": \"اجرای زودهنگام یا بدون ارزش کافی ممکن است دفاع بعدی را پرهزینه کند.\",\n      \"mistake\": \"استفاده برای آسیب جزئی وقتی مسیر مشخصی برای کسب ارزش وجود ندارد.\",\n      \"quality\": \"مقدار دقیق آسیب به سطح کارت و نسخه Balance وابسته است.\"\n    },\n    \"28000011\": {\n      \"focus\": \"طلسم سبک زمینی با کاربرد پاک‌سازی، عقب‌راندن و کنترل ریتم.\",\n      \"attack\": \"برای برداشتن دفاع کم‌جان در مسیر Win Condition قابل بررسی است.\",\n      \"defense\": \"در برابر گروه‌های زمینی کاربرد دارد، اما پاسخ مستقیم به گروه‌های هوایی نیست.\",\n      \"threats\": \"کارت‌های هوایی و نیروهایی که با یک اجرای طلسم از بین نمی‌روند.\",\n      \"mistake\": \"مصرف بی‌برنامه طلسم سبک پیش از فشار قابل‌پیش‌بینی حریف.\",\n      \"quality\": \"رفتار دقیق کارت و اهداف قابل‌اصابت با نسخه فعلی بازی بررسی شود.\"\n    }\n  }\n}";
var MANIFEST="{\n  \"id\": \"/\",\n  \"name\": \"Clash Royale Companion — Development\",\n  \"short_name\": \"CRC Coach\",\n  \"description\": \"مربی و دک‌ساز آزمایشی Clash Royale Companion\",\n  \"start_url\": \"/?source=pwa\",\n  \"scope\": \"/\",\n  \"display\": \"standalone\",\n  \"background_color\": \"#080f1e\",\n  \"theme_color\": \"#080f1e\",\n  \"lang\": \"fa\",\n  \"dir\": \"rtl\",\n  \"icons\": [\n    {\n      \"src\": \"/icon.svg\",\n      \"sizes\": \"any\",\n      \"type\": \"image/svg+xml\",\n      \"purpose\": \"any maskable\"\n    }\n  ]\n}";
var ICON_SVG="<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\" role=\"img\" aria-labelledby=\"title\">\n<title>Clash Royale Companion</title>\n<defs><linearGradient id=\"bg\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop stop-color=\"#0f3449\"/><stop offset=\"1\" stop-color=\"#09111e\"/></linearGradient><linearGradient id=\"gold\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop stop-color=\"#ffe9ab\"/><stop offset=\"1\" stop-color=\"#d99d4d\"/></linearGradient></defs>\n<rect width=\"512\" height=\"512\" rx=\"114\" fill=\"url(#bg)\"/>\n<rect x=\"20\" y=\"20\" width=\"472\" height=\"472\" rx=\"99\" fill=\"none\" stroke=\"#f4ce83\" opacity=\".27\" stroke-width=\"7\"/>\n<path d=\"M110 188l70 64 75-119 75 119 72-64-28 176H139z\" fill=\"url(#gold)\" stroke=\"#d79745\" stroke-width=\"7\" stroke-linejoin=\"round\"/>\n<path d=\"M144 384h228\" stroke=\"#fff2c4\" stroke-width=\"22\" stroke-linecap=\"round\"/>\n<circle cx=\"110\" cy=\"182\" r=\"18\" fill=\"#ffeac0\"/><circle cx=\"255\" cy=\"131\" r=\"20\" fill=\"#ffeac0\"/><circle cx=\"402\" cy=\"182\" r=\"18\" fill=\"#ffeac0\"/>\n</svg>";
var SW="const VERSION='crc-mvp-static-v10';\nconst ASSETS=['/','/styles.css','/app.js','/battle-insights.js','/owned-options.js','/offline-coach.js','/coach-chat.js','/backend-client.js','/catalog.json','/guides.json','/icon.svg'];\nself.addEventListener('install',event=>{\n  event.waitUntil(caches.open(VERSION).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()));\n});\nself.addEventListener('activate',event=>{\n  event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('crc-mvp-static-')&&key!==VERSION).map(key=>caches.delete(key)))).then(()=>self.clients.claim()));\n});\nself.addEventListener('fetch',event=>{\n  const req=event.request, u=new URL(req.url);\n  if(req.method!=='GET'||u.origin!==self.location.origin||!ASSETS.includes(u.pathname))return;\n  event.respondWith(fetch(req).then(async response=>{\n    if(response.ok){const c=await caches.open(VERSION);await c.put(req,response.clone());}\n    return response;\n  }).catch(async()=>await caches.match(req,{ignoreSearch:true})||new Response('Offline asset unavailable',{status:503})));\n});\n";
var CARD_LIBRARY=JSON.parse(CATALOG_JSON);
var LIBRARY_MAP=new Map(CARD_LIBRARY.cards.map(function(c){return [c.id,c]}));
function respond(content,type,status){
  return new Response(content,{status:status||200,headers:{
  "Content-Type":type,"Cache-Control":"no-store","X-Content-Type-Options":"nosniff",
  "Referrer-Policy":"no-referrer","X-Robots-Tag":"noindex, nofollow",
  "Cross-Origin-Resource-Policy":"same-origin"}});
}
function jsonResponse(obj,status){return respond(JSON.stringify(obj),"application/json; charset=utf-8",status);}
function error(code,message,status){return jsonResponse({error:{code:code,message:message},mode:"sample-only",supercell_live:false},status||400);}
function factsFor(ids){
 if(!Array.isArray(ids)||ids.length!==8||ids.some(function(x){return !Number.isSafeInteger(x);})||new Set(ids).size!==8)return {status:422,error:"دک باید دقیقاً ۸ کارت یکتا داشته باشد.",code:"INVALID_DECK"};
 var chosen=ids.map(function(id){return LIBRARY_MAP.get(id);});
 if(chosen.some(function(c){return !c||c.type==="support";}))return {status:422,error:"یک یا چند کارت ناشناخته یا نامعتبر است.",code:"UNKNOWN_CARD"};
 var costs=chosen.map(function(c){return c.elixir;});
 var missing=chosen.filter(function(c){return !Number.isInteger(c.elixir)||c.elixir<0;}).map(function(c){return c.id;});
 if(missing.length)return {status:200,facts:{average_elixir:null,cycle_cost_four_cheapest:null,unknown_card_ids:missing,expensive_cards_count:null,cheap_cards_count:null},valid:true};
 var cycle=costs.slice().sort(function(a,b){return a-b;}).slice(0,4).reduce(function(a,b){return a+b;},0);
 return {status:200,valid:true,facts:{average_elixir:costs.reduce(function(a,b){return a+b;},0)/8,cycle_cost_four_cheapest:cycle,unknown_card_ids:[],expensive_cards_count:costs.filter(function(x){return x>=5;}).length,cheap_cards_count:costs.filter(function(x){return x<=2;}).length}};
}
async function serve(request){
  var url=new URL(request.url),path=url.pathname;
  if(request.method==="GET"&&path==="/")return new Response(HTML,{status:200,headers:{"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store","X-Robots-Tag":"noindex, nofollow","X-Content-Type-Options":"nosniff","Referrer-Policy":"no-referrer","X-Frame-Options":"DENY","Content-Security-Policy":"default-src 'none'; script-src 'self'; style-src 'self' https://fonts.googleapis.com 'unsafe-inline'; font-src https://fonts.gstatic.com; img-src 'self' https://api-assets.clashroyale.com; worker-src 'self'; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"}});
  if(request.method==="GET"&&path==="/styles.css")return respond(CSS,"text/css; charset=utf-8");
  if(request.method==="GET"&&path==="/app.js")return respond(APP,"application/javascript; charset=utf-8");
  if(request.method==="GET"&&path==="/battle-insights.js")return respond(BATTLE_INSIGHTS,"application/javascript; charset=utf-8");
  if(request.method==="GET"&&path==="/offline-coach.js")return respond(OFFLINE_COACH,"application/javascript; charset=utf-8");
  if(request.method==="GET"&&path==="/coach-chat.js")return respond(COACH_CHAT,"application/javascript; charset=utf-8");
  if(request.method==="GET"&&path==="/owned-options.js")return respond(OWNED_OPTIONS,"application/javascript; charset=utf-8");
  if(request.method==="GET"&&path==="/backend-client.js")return respond(BACKEND_CLIENT,"application/javascript; charset=utf-8");
  if(request.method==="GET"&&path==="/catalog.json")return respond(CATALOG_JSON,"application/json; charset=utf-8");
  if(request.method==="GET"&&path==="/guides.json")return respond(GUIDES_JSON,"application/json; charset=utf-8");
  if(request.method==="GET"&&path==="/manifest.webmanifest")return respond(MANIFEST,"application/manifest+json; charset=utf-8");
  if(request.method==="GET"&&path==="/icon.svg")return respond(ICON_SVG,"image/svg+xml; charset=utf-8");
  if(request.method==="GET"&&path==="/sw.js")return new Response(SW,{headers:{"Content-Type":"application/javascript; charset=utf-8","Cache-Control":"no-store","Service-Worker-Allowed":"/","X-Content-Type-Options":"nosniff"}});
  if(request.method==="GET"&&path==="/health")return jsonResponse({status:"ok",service:"crc-mvp-site",version:"0.2.0",mode:"sample-only",supercell_live:false});
  if(request.method==="GET"&&path==="/api/v1/health/live")return jsonResponse({status:"ok"});
  if(request.method==="GET"&&path==="/api/v1/health/ready")return jsonResponse({status:"sample-only",live_supercell:false});
  if(request.method==="GET"&&path==="/api/v1/capabilities")return jsonResponse({schema_version:"1.0",live_lookup_enabled:false,provider:null,player_tag_verifies_ownership:false,battle_log_full_history:false,safe_public_exposure:false,ai_coach_enabled:false,ai_external_data_requires_consent:true,mode:"sample-only"});
  if(request.method==="GET"&&path==="/api/cards")return jsonResponse({mode:"sample-only",cards:CARD_LIBRARY.cards.filter(function(c){return c.type!=="support";}).map(function(c){return {id:c.id,name:c.name,elixir:c.elixir};}),sample_decks:CARD_LIBRARY.predefined});
  if(request.method==="GET"&&path==="/api/v1/catalog/cards")return jsonResponse({items:CARD_LIBRARY.cards.map(function(c){return {id:c.id,name:c.name,elixir_cost:c.elixir,type:c.type,icon_url:c.icon};}),catalog_version:CARD_LIBRARY.revision,source:{provider:"local-seed",stale:true},mode:"sample-only"});
  if(request.method==="GET"&&path.startsWith("/api/v1/players/"))return error("LIVE_BACKEND_NOT_CONFIGURED","ارتباط زنده بازیکن در محیط Cloudflare رایگان فعال نشده است.",503);
  if(request.method==="POST"&&(path==="/api/analyze"||path==="/api/v1/decks/validate"||path==="/api/v1/analyses")){
    var raw=await request.text();if(raw.length>6000)return error("PAYLOAD_TOO_LARGE","درخواست بیش از حد بزرگ است.",413);
    var data;try{data=JSON.parse(raw);}catch(e){return error("INVALID_JSON","JSON نامعتبر است.",400);}
    var ids=path==="/api/v1/analyses"?data&&data.deck&&data.deck.card_ids:data&&data.card_ids;
    var check=factsFor(ids);
    if(check.status!==200)return error(check.code,check.error,check.status);
    if(path==="/api/v1/decks/validate")return jsonResponse({valid:check.valid,errors:[],metrics:check.facts,mode:"sample-only"});
    if(path==="/api/v1/analyses")return jsonResponse({engine_version:"arithmetic-sample-0.2",ruleset_version:"unreviewed",facts:check.facts,findings:[],recommendations:[],mode:"sample-only",disclaimer:"Sample card data; no tactical coaching or win prediction."});
    return jsonResponse({valid:check.valid,facts:check.facts,mode:"sample-only"});
  }
  if(path==="/api/v1/coach/chat")return error("AI_COACH_DISABLED","مربی آنلاین در سایت عمومی فعال نیست.",503);
  if(request.method==="GET"&&path==="/favicon.ico")return new Response(null,{status:204});
  return error("NOT_FOUND","این مسیر در سایت آزمایشی موجود نیست.",404);
}
addEventListener("fetch",function(event){event.respondWith(serve(event.request));});
